import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceCubeClockDelta {
 static final String P="local/lito381/server/",N=P+"NativeSourceCubeClock",H=P+"GameHub",C=P+"NativeSourceCubePlacement";
 static final List<String>ENGINES=List.of(P+"BattleCubeIgnitionEffects",P+"BattleCubeQuakeEffects",P+"BattleCubeShockEffects",P+"BattleCubeHarmonyEffects"),OWNERS=java.util.stream.Stream.concat(java.util.stream.Stream.of(H,C),ENGINES.stream()).toList();
 static void need(boolean v,String why){if(!v)throw new AssertionError(why);}
 static void remove(MethodNode m,AbstractInsnNode node,int prior,int after){var first=node;for(int i=0;i<prior;i++)first=FreezeAcceptedMethods.prev(first);var last=node;for(int i=0;i<after;i++)last=FreezeSourceTargetDelta.next(last);var stop=last.getNext();for(var n=first;n!=stop;){var next=n.getNext();m.instructions.remove(n);n=next;}}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var n=jar.getJarEntry(e.getName());need(n!=null,"retain all original entries");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(n).readAllBytes()))changed.add(e.getName());}need(changed.equals(new HashSet<>(OWNERS.stream().map(x->x+".class").toList())),"six original Hub/placement/scan owners");int count=0,init=0,begin=0,close=0,compare=0,cadence=0;
  for(String owner:OWNERS){var before=FreezeSourceTargetDelta.read(base,owner);var after=FreezeSourceTargetDelta.read(jar,owner);need(after.fields.size()==before.fields.size()+(owner.equals(H)?4:0),"four bounded clock states on original Hub only");for(int k=0;k<before.fields.size();k++){var x=before.fields.get(k);var y=after.fields.get(k);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields retained");}if(owner.equals(H)){var expected=List.of("nativeSourceCubeBurnPhase","nativeSourceCubeQuakePhase","nativeSourceCubeShockPhase","nativeSourceCubeHarmonyPhase");for(int k=0;k<4;k++){var f=after.fields.get(before.fields.size()+k);need(f.name.equals(expected.get(k))&&f.desc.equals("Ljava/lang/Object;")&&f.access==ACC_VOLATILE,"bounded visible original clock owner");}}
   for(var old:before.methods){var now=after.methods.stream().filter(m->m.name.equals(old.name)&&m.desc.equals(old.desc)).findFirst().orElseThrow();if(owner.equals(C)&&old.name.equals("cadence")){for(var node:now.instructions.toArray())if(node instanceof LdcInsnNode ldc&&Long.valueOf(1000).equals(ldc.cst)&&FreezeSourceTargetDelta.next(node) instanceof JumpInsnNode jump&&jump.getOpcode()==GOTO){need(FreezeAcceptedMethods.prev(node) instanceof JumpInsnNode cond&&cond.getOpcode()==IFEQ,"only old Source interval branch");ldc.cst=500L;cadence++;}}
    for(var node:now.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N))switch(call.name){
     case "init"->{need(owner.equals(H)&&old.name.equals("<init>")&&FreezeAcceptedMethods.prev(call).getOpcode()==DUP&&FreezeSourceTargetDelta.next(call) instanceof InvokeDynamicInsnNode dyn&&Arrays.stream(dyn.bsmArgs).anyMatch(arg->arg instanceof org.objectweb.asm.Handle h&&h.getOwner().equals(H)&&h.getName().equals("groundTickSafely")),"before exact original ground task publication");remove(now,call,1,0);init++;}
     case "begin"->{need(owner.equals(H)&&(old.access&ACC_SYNCHRONIZED)!=0,"original per-type Hub monitor");var type=FreezeAcceptedMethods.prev(call);need(type instanceof LdcInsnNode ldc&&Objects.equals(ldc.cst,List.of("cubeTicks","cubeQuakeTicks","cubeShockTicks","cubeHarmonyTicks").indexOf(old.name)),"matching original type collector before rooms");remove(now,call,3,0);begin++;}
     case "close"->{need(owner.equals(H)&&old.name.equals("close"),"original Hub close completion");remove(now,call,1,0);close++;}
     case "compare"->{need(ENGINES.contains(owner)&&old.name.equals("advance"),"new-effect scan only");var load=FreezeAcceptedMethods.prev(call);var field=FreezeAcceptedMethods.prev(load);need(load instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==0&&field instanceof FieldInsnNode f&&f.getOpcode()==GETFIELD&&f.owner.equals(owner+"$CubeLease")&&f.name.equals("nextScanAtNanos"),"same original scan deadline operands");now.instructions.remove(load);now.instructions.set(call,new InsnNode(LCMP));compare++;}
     default->throw new AssertionError("unreviewed Source clock port");
    }need(Arrays.equals(FreezeSourceTargetDelta.body(before,old,old.name,old.access),FreezeSourceTargetDelta.body(after,now,old.name,old.access)),"independent original inverse "+owner+old.name);count++;}need(after.methods.size()==before.methods.size(),"no new original owner methods");
  }
  need(init==1&&begin==4&&close==1&&compare==4&&cadence==1,"exact original clock startup/type/close/scan and corrected Source branch");var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName())){fresh.add(e.getName());var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));for(var f:c.fields)need(e.getName().endsWith("$Phase.class")?f.desc.equals("J")&&(f.access&ACC_FINAL)!=0:f.name.equals("PERIOD")&&f.desc.equals("J")&&(f.access&(ACC_STATIC|ACC_FINAL))==(ACC_STATIC|ACC_FINAL),"clock carries only primitive deadlines, no producer or actor");for(var m:c.methods)for(var n:m.instructions){need(n.getOpcode()!=MONITORENTER,"no new lock order");if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor")&&!t.desc.equals(P+"ClientSession")&&!t.desc.equals(H),"no workers or bound game fixtures");if(n instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!Set.of("schedule","scheduleAtFixedRate","scheduleWithFixedDelay","takePlayerDamage","applyDamage","enqueueBattle","setChargeCount").contains(call.name),"reuse original scheduler, no new HP/persistence");}}need(fresh.equals(Set.of(N+".class",N+"$Phase.class")),"clock helper and primitive phase only");System.out.println("PASS independent cube clock inverse: "+count+" original methods; actual bootstrap0/1000 replaces leaf-start500 assumption, only new-effect global scan phase changes; original status/HP/cost/RNG/scheduler/output retained");
 }}
}
